from collections import deque

def find_components_with_details(grid, target_color):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color and (r, c) not in visited:
                component = []
                visited.add((r, c))
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    component.append((cr, cc))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))
                components.append(component)
    return components

