def count_4x4(grid):
    rows, cols = len(grid), len(grid[0])
    subtrees = {}
    for r in range(rows - 3):
        for c in range(cols - 3):
            key = tuple(tuple(grid[r+i][c+j] for j in range(4)) for i in range(4))
            subtrees[key] = subtrees.get(key, 0) + 1
    return [[v for k, v in sorted(subtrees.items(), key=lambda x: -x[1])[:10]] for _ in [None]]

